class Emiter {
  sluchacze = {};
  on(nazwa, fn) {
    (this.sluchacze[nazwa] ||= []).push(fn);
  }
  emit(nazwa, ...args) {
    (this.sluchacze[nazwa] || []).forEach(fn => fn(...args));
  }
}

class Licznik {
  n = 0;
  plus(x) {
    this.n += x;
  }
}

